# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.rounding import label_rounded_spans


def labels_for(texts, step):
    return label_rounded_spans(map(parse_span, texts), step)


class RoundingTests(unittest.TestCase):
    def test_already_on_step(self):
        self.assertEqual(
            labels_for(["09:00-17:15"], 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_rounds_to_nearest(self):
        self.assertEqual(
            labels_for(["08:53-17:07"], 15),
            ["09:00-17:00 (8h 0m)"]
        )

    def test_halfway_rounds_up(self):
        self.assertEqual(
            labels_for(["09:05-10:04"], 10),
            ["09:10-10:00 (0h 50m)"]
        )

    def test_several_spans_keep_order(self):
        self.assertEqual(
            labels_for(["13:00-14:20", "09:00-10:40"], 30),
            ["13:00-14:30 (1h 30m)", "09:00-10:30 (1h 30m)"]
        )

    def test_rounds_up_to_midnight(self):
        self.assertEqual(
            labels_for(["22:00-23:58"], 5),
            ["22:00-24:00 (2h 0m)"]
        )

    def test_empty_list(self):
        self.assertEqual(label_rounded_spans([], 15), [])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 120):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    labels_for(["09:00-10:00"], step)

    def test_span_shrinking_to_nothing_raises(self):
        with self.assertRaises(ValueError):
            labels_for(["09:01-09:05"], 15)


if __name__ == "__main__":
    unittest.main()
